def _stage_artifacts(run: PipelineRun, stage: str) -> list[Path]:
    return [
        run.run_path / relative_path
        for relative_path in REQUIRED_ARTIFACTS.get(stage, ())
    ]


def _dynamic_stage_complete(run: PipelineRun, stage: str) -> bool:
    if stage == "features":
        feature_runs = run.extra.get("feature_runs") or []
        if feature_runs:
            return any(
                entry.get("status") == "completed"
                for entry in feature_runs
            )
        features_dir = run.features_dir or (run.run_path / "features")
        return (features_dir / "train_validation_set.pkl").is_file()
    if stage == "training":
        model_runs = run.extra.get("model_runs") or []
        if model_runs:
            return all(
                entry.get("status") == "completed"
                for entry in model_runs
            )
        runs = run.extra.get("training_runs") or []
        return bool(
            runs
            and any(
                path.is_file()
                for path in (
                    run.run_path / runs[-1]["output_dir"]
                ).rglob("*")
            )
        )
    if stage == "holdout":
        return any(
            entry.get("status") == "completed"
            for entry in run.extra.get("holdout_runs") or []
        )
    if stage == "model_reports":
        path = (run.extra.get("artifacts") or {}).get("local", {}).get(
            "model_report_excel"
        )
        return bool(path and (run.run_path / path).is_file())
    return True


def should_skip_stage(
    run: PipelineRun,
    stage: str,
    *,
    resume: bool,
    force: bool,
) -> bool:
    if force or not resume:
        return False
    status = (run.extra.get("stages") or {}).get(stage, {}).get("status")
    if status not in {"completed", "skipped"}:
        return False

