    if any(not path.is_file() for path in artifacts):
        return False
    checksums = (run.extra.get("resume") or {}).get("artifact_checksums") or {}
    for path in artifacts:
        relative = str(path.relative_to(run.run_path))
        expected = checksums.get(relative)
        if expected and sha256_file(path) != expected:
            return False
    return _dynamic_stage_complete(run, stage)


