def list_feature_runs(base_run: PipelineRun) -> list[Path]:
    """Newest-first list of feature-run directories under a base run."""
    root = base_run.run_path / FEATURE_RUNS_DIR_NAME
    if not root.is_dir():
        return []
    runs = [path for path in root.iterdir() if path.is_dir()]
    return sorted(runs, key=lambda path: path.stat().st_mtime, reverse=True)


def record_feature_run_on_base_run(
    base_run: PipelineRun,
    feature_run: FeatureRun,
    *,
    persist: bool = True,
) -> None:
    """Append feature-run lineage to the parent base-run manifest."""
    relative = feature_run.feature_run_path.relative_to(
        base_run.run_path
    ).as_posix()
    selection = feature_run.extra.get("feature_selection") or {}
    entry = {
        "feature_run_id": feature_run.feature_run_id,
        "path": relative,
        "group_comparison": feature_run.extra.get("group_comparison"),
        "requested_feature_count": selection.get("requested_feature_count"),
        "selected_feature_count": selection.get("selected_feature_count"),
        "extract_only": bool(feature_run.extra.get("extract_only")),
        "status": (feature_run.extra.get("stages") or {}).get("features", {}).get(
            "status", "pending"
        ),
    }
    base_run.extra.setdefault("feature_runs", []).append(entry)
    if persist:
        base_run.save_manifest()


def _refuse_extract_only(feature_run: FeatureRun) -> None:
    raise ValueError(
        f"Feature run {feature_run.feature_run_id} is extract-only (made for a "
        "holdout run): it has features_all but no selected features or "
        "train/test sets. Run the features stage without extract-only to train."
    )


