def features_extract_only_for_plan(plan: Sequence[str]) -> bool:
    """Whether the features stage can stop after extraction (SW-589 G18).

    True when the plan runs holdout but not training: the holdout stage reads
    only ``features_all`` and selects features again inside every holdout, so
    the whole-pool selection would be computed and never used.
    """
    stages = set(plan)
    return "features" in stages and "holdout" in stages and "training" not in stages


def _clinical_paths_from_run(run: PipelineRun) -> list[Path]:
    value = run.clinical_path
    if value is None:
        return []
    if isinstance(value, list):
        return [Path(path).expanduser().resolve() for path in value]
    return [Path(value).expanduser().resolve()]


