        if median == 0:
            mask = frame[column].gt(0)
            add(f"{name} >0 vs ==0 (median was 0)", mask, "any_blip", "no_blip")
        else:
            mask = frame[column].ge(median)
            add(f"{name} median-split ({median:.2f})", mask, "high", "low")

    median_date = frame["median_file_write_time"].median()
    if pd.notna(median_date):
        late = frame["median_file_write_time"].ge(median_date)
        add(f"date median-split ({pd.Timestamp(median_date).date()})", late, "late", "early")

    era_start = pd.Timestamp("2025-06-01", tz="UTC")
    late_era = frame["median_file_write_time"].ge(era_start)
    if int(late_era.sum()) >= 3 and int((~late_era).sum()) >= 3:
        add("date era split 2025-06-01", late_era, "late>=2025-06", "early<2025-06")
    return pd.DataFrame(rows)


