def _apply_thresholds(df_subset: pd.DataFrame) -> tuple[pd.DataFrame, float]:
    if strategy == "manual":
        threshold = 0.5 if manual_threshold is None else float(manual_threshold)
    else:
        threshold_source_df = df_subset
        if "set" in df_subset.columns:
            roc_source_df = df_subset[
                df_subset["set"].astype(str).str.lower().eq(roc_set_normalized)
            ]
            if len(roc_source_df):
                threshold_source_df = roc_source_df
        roc_df = threshold_source_df[
            (threshold_source_df["accuracy_bin"] != "grayzone")
            & threshold_source_df[prob_col].notna()
            & threshold_source_df[group_col].notna()
        ].copy()
        y_true = roc_df[group_col].apply(lambda v: 1 if v == pos_label else 0).to_numpy()
        scores = roc_df[prob_col].astype(float).to_numpy()
        if len(np.unique(y_true)) < 2:
            raise ValueError("Cannot compute ROC threshold because both classes are not present.")
        fpr, tpr, thresholds = roc_curve(y_true, scores)
        best_idx = _select_roc_threshold_index(strategy, fpr, tpr, thresholds)
        threshold = float(thresholds[best_idx])

    def _estimated_label(row) -> str:
        if row["accuracy_bin"] == "grayzone":
            return "grayzone"
        return pos_label if float(row[prob_col]) >= threshold else neg_label

    df_subset = df_subset.copy()
    df_subset["estimated_label"] = df_subset.apply(_estimated_label, axis=1)
    df_subset["threshold_strategy"] = threshold_strategy
    df_subset["threshold_value"] = threshold
    return df_subset, threshold

